def encode(message):
    result = []
    vowels = {'a', 'e', 'i', 'o', 'u'}
    for c in message:
        if c.isalpha():
            new_char = c.swapcase()
            if new_char.lower() in vowels:
                if new_char.isupper():
                    shifted = (ord(new_char) - ord('A') + 2) % 26 + ord('A')
                else:
                    shifted = (ord(new_char) - ord('a') + 2) % 26 + ord('a')
                new_char = chr(shifted)
            result.append(new_char)
        else:
            result.append(c)
    return ''.join(result)
